) {
    const key = profile?.name ?? '';
    const snapshot = useSyncExternalStore(
        (onStoreChange) => {
            service.addEventListener(`catalog:${key}`, onStoreChange);

            return () => service.removeEventListener(`catalog:${key}`, onStoreChange);
